"""Create stage-linked live issues from existing source and implementation evidence."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
entries=[
 ('01','연구의 공백은 무엇이고 무엇을 검정하는가?','문헌·설계 확인','저자는 기존 NLR 중심 연구와 SIRI–FI 근거 및 미국 집단 일반화의 공백을 제시했다. 이 작업은 해당 문헌 전체를 새로 체계적 고찰한 것은 아니다.','V2-P01','조건부 설명','인과효과나 미래 예측 성능이 아니라 같은 조사 시점의 보정된 연관성이 주 추정 대상이다.'),
 ('02','같은 혈구 수에서 만든 네 지표가 독립적인 증거인가?','통계적 타당성','NLR·MLR·SIRI·SII는 세포 수를 공유한다. 기존 후보 자료의 상관 계산을 재사용한다.','V2-E01','부분 해결','지표 간 의존성을 확인했으나 각각이 염증을 완전히 대표한다는 타당성 검증은 아니다.'),
 ('03','저자의 36항목 FI를 정확히 계산할 수 있는가?','미공개 구현','항목 목록은 확인되지만 설문 이분화·허용 결측·분모 규칙이 충분하지 않다. operational36 규칙은 분석자 가정이다.','V2-P01','미해결','이미 계산한 FI 후보와 대안 코딩 결과는 유지하지만 저자 FI와 같다고 주장하지 않는다.'),
 ('04','대상자 수 차이가 연령 경계나 결측에서 생겼는가?','미공개 구현·자료 감사','원문 ≥50와 >50 문구가 혼용된다. 두 경계의 실제 인원을 동일한 필터에서 대조한다.','V2-I01','분석 후 갱신','후보 인원에 맞는 경계를 역으로 고르지 않는다. 공변량 결측152명과 음주 결측627명의 처리도 미공개다.'),
 ('05','Table1의 인원·비율·중앙값은 같은 분모와 설계를 쓰는가?','보고 정합성','3729/13507은 27.61%이나 원문은24%를 보고한다. 가중·비가중 설명이 일관되지 않아 원인을 확정할 수 없다.','V2-P01','부분 해결','가중 비율과 단순 빈도의 차이는 설명 가능하지만 이 표의 숨은 계산 규칙을 확인한 것은 아니다.'),
 ('06','OR의 1단위는 무엇이고 로그의 밑을 바꾸면 무엇이 바뀌는가?','계산·해석 검토','ln 지표 1단위는 지표 e배, log10 1단위는10배다. 같은 배수 변화로 환산하면 같은 추정이다.','V2-I01','분석 후 갱신','OR 수치가 다르다고 실제 적합 확률이나 생물학적 효과가 바뀌었다고 읽지 않는다.'),
 ('07','연속 로그 지표와 logit의 직선 관계가 적절한가?','통계적 타당성','설명변수의 정규성 대신 결과와의 함수 관계를 확인한다. 고정 df3 자연스플라인의 추가2자유도를 검정한다.','V2-I01','분석 후 갱신','이 진단은 분석자가 정한 모형이다. 원문 RCS knot·기준점이 확인된 재현은 아니다.'),
 ('08','같은 보정 모형을 구현했을 때 원문 OR와 비교할 수 있는가?','미공개 구현·추정 비교','Model1의 공변량 구조를 구현했어도 FI 코딩·표본·로그 밑·조사설계 처리의 차이가 남는다.','V2-I01','분석 후 갱신','로그 척도와 모형이 같아도 분석집단이 다르면 정확 재현 통과로 판정하지 않는다. Model2의 미공개 정의는 남긴다.'),
 ('09','논문과 과제의 사분위 분석은 같은 질문인가?','질문·구현 구분','논문은 염증지표군→노쇠 여부 OR, 과제는 FI군→염증지표 평균 차이다. 이번에는 전자의 Model1 후보를 추가한다.','V2-I01','분석 후 갱신','같은 자료를 사용해도 X와Y가 달라 결과를 바꾸어 읽을 수 없다.'),
 ('10','곡선·민감도·모의실험이 논문의 결론을 어디까지 지지하는가?','통계적 타당성','정의 변경, 조사설계, 함수 형태와 이상적 검정 원리·실제 절차 검증의 적용 범위를 구분한다.','V2-Q01','검토 후 갱신','계산의 정확성, 방법의 조건부 적절성, 측정 타당성, 인과성은 서로 다른 판단이다.')]
issues=[]
for stage,q,kind,evidence,task,state,limit in entries:
 issues.append(dict(issue_id='ISSUE-'+stage,stage_id=stage,question=q,kind=kind,source_summary=evidence,task_id=task,status=state,interpretation_limit=limit))
(ROOT/'memory/issues.json').write_text(json.dumps(issues,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Registered 10 stage-linked questions; computation-dependent judgments remain pending.')
